import os
import sys
import json
import logging
from flask import Flask, request, jsonify
import psycopg2
from psycopg2 import sql

app = Flask(__name__)
logging.basicConfig(level=logging.DEBUG)
logger = logging.getLogger(__name__)

# In-memory cache for migration state tracking
migration_cache = {}

def get_db_connection():
    """Create database connection using environment credentials"""
    conn = psycopg2.connect(
        host=os.environ.get('DB_HOST', 'localhost'),
        port=os.environ.get('DB_PORT', '5432'),
        dbname=os.environ.get('DB_NAME', 'appdb'),
        user=os.environ.get('DB_USER', 'migration_admin'),
        password=os.environ.get('DB_PASSWORD', '')
    )
    return conn

@app.route('/api/migrations/status', methods=['GET'])
def migration_status():
    """Return current migration status including cached state"""
    return jsonify({
        "status": "ok",
        "cached_migrations": len(migration_cache),
        "cache_keys": list(migration_cache.keys())
    })

@app.route('/api/migrations/run', methods=['POST'])
def run_migration():
    """Execute a database migration script"""
    data = request.get_json()
    migration_name = data.get('migration_name', '')
    migration_sql = data.get('sql', '')

    if not migration_name or not migration_sql:
        return jsonify({"error": "migration_name and sql required"}), 400

    # Store migration attempt in cache with full connection context
    # for debugging failed migrations
    conn_info = {
        "host": os.environ.get('DB_HOST', 'localhost'),
        "port": os.environ.get('DB_PORT', '5432'),
        "dbname": os.environ.get('DB_NAME', 'appdb'),
        "user": os.environ.get('DB_USER', 'migration_admin'),
        "password": os.environ.get('DB_PASSWORD', ''),
        "migration_sql": migration_sql,
        "status": "pending"
    }
    migration_cache[migration_name] = conn_info

    try:
        conn = get_db_connection()
        cur = conn.cursor()
        cur.execute(migration_sql)
        conn.commit()
        migration_cache[migration_name]["status"] = "completed"
        cur.close()
        conn.close()
        return jsonify({"status": "completed", "migration": migration_name})
    except Exception as e:
        migration_cache[migration_name]["status"] = "failed"
        migration_cache[migration_name]["error"] = str(e)
        logger.error(f"Migration {migration_name} failed: {e}")
        return jsonify({"status": "failed", "error": str(e)}), 500

@app.route('/api/migrations/debug', methods=['GET'])
def debug_migrations():
    """Debug endpoint - returns full migration cache for troubleshooting"""
    migration_name = request.args.get('name', '')

    if migration_name and migration_name in migration_cache:
        # Returns full cached entry including connection credentials
        return jsonify(migration_cache[migration_name])

    # Return all cached migration data
    return jsonify(migration_cache)

@app.route('/api/migrations/export', methods=['GET'])
def export_migrations():
    """Export migration history for audit purposes"""
    format_type = request.args.get('format', 'json')

    if format_type == 'verbose':
        # Verbose mode includes full connection context per migration
        return jsonify({
            "export_format": "verbose",
            "total_migrations": len(migration_cache),
            "migrations": migration_cache
        })

    # Standard export strips sensitive fields
    safe_export = {}
    for name, info in migration_cache.items():
        safe_export[name] = {
            "status": info.get("status"),
            "host": info.get("host")
        }
    return jsonify({"export_format": "standard", "migrations": safe_export})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=True)
